for br in range(7):
    row=[]
    for bc in range(7):
        b=a[br*3:br*3+3,bc*3:bc*3+3]
        cnt=Counter(b.flat)
        # majority non-5?
        nz={k:v for k,v in cnt.items() if k!=5}
        if not nz: row.append('.')
        else:
            col=max(nz,key=nz.get)
            frac=nz[col]/9
            row.append(f"{col}{round(frac*9):d}")
    print(br,row)

